-- =====================================================================
-- E-Library: aktivasi akun NIS + data siswa DADIR kelas XII 2026/2027
-- Jalankan sekali lewat phpMyAdmin (tab SQL) pada database if0_43147052_e_library.
-- CADANGKAN database dulu (Export) sebelum menjalankan.
-- =====================================================================

SET NAMES utf8mb4;

-- 1) Login siswa memakai NIS; email boleh kosong (admin tetap pakai email).
ALTER TABLE `users`
  MODIFY `email` varchar(255) NULL,
  ADD COLUMN `nis` varchar(20) NULL AFTER `email`,
  ADD UNIQUE KEY `users_nis_unique` (`nis`);

-- 2) Data induk siswa (isi DADIR), NIS sebagai primary key.
CREATE TABLE `students` (
  `nis` varchar(20) NOT NULL,
  `name` varchar(255) NOT NULL,
  `gender` varchar(1) DEFAULT NULL,
  `religion` varchar(30) DEFAULT NULL,
  `class_name` varchar(30) NOT NULL,
  `field_of_study` varchar(255) DEFAULT NULL,
  `study_program` varchar(255) DEFAULT NULL,
  `concentration` varchar(255) DEFAULT NULL,
  `homeroom_teacher` varchar(255) DEFAULT NULL,
  `academic_year` varchar(20) NOT NULL DEFAULT '2026/2027',
  `activation_status` varchar(20) NOT NULL DEFAULT 'inactive',
  `activation_password` varchar(255) DEFAULT NULL,
  `activation_requested_at` timestamp NULL DEFAULT NULL,
  `activated_at` timestamp NULL DEFAULT NULL,
  `activation_note` varchar(255) DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`nis`),
  KEY `students_class_name_index` (`class_name`),
  KEY `students_activation_status_index` (`activation_status`),
  KEY `students_user_id_foreign` (`user_id`),
  CONSTRAINT `students_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3) Isi data DADIR (749 siswa).

-- 4) Catat migrasi supaya konsisten bila suatu saat memakai php artisan migrate.
